<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/classes/GreenPortalDatabase.php';
$env=GreenPortalDatabase::env();$out=[];$ok=true;
foreach(['gatlas_dbp','gmodelo_dbp','gmodelo2_dbp'] as $db){$p=GreenPortalDatabase::connect($env,$db,'GPT');$migration=(int)$p->query("SELECT COUNT(*) FROM registros_migracao WHERE codigo_migracao='GREEN_AI_APPROVED_TASKS_192' AND status='CONCLUIDA'")->fetchColumn();$missing=(int)$p->query("SELECT COUNT(*) FROM ml_potenciais p WHERE p.status='APROVADO' AND NOT EXISTS (SELECT 1 FROM green_tasks t WHERE t.chave_idempotencia=CONCAT('IA-POTENCIAL:',p.codpotencial))")->fetchColumn();$tasks=(int)$p->query("SELECT COUNT(*) FROM green_tasks WHERE tipo='IA_APROVACAO'")->fetchColumn();$alerts=(int)$p->query("SELECT COUNT(*) FROM alertas WHERE titulo='Tarefa criada a partir de IA'")->fetchColumn();$audits=(int)$p->query("SELECT COUNT(*) FROM logs_auditoria WHERE transacao='modulolegal_potenciais.php' AND acao='CRIAR_TAREFA'")->fetchColumn();$duplicate=(int)$p->query("SELECT COUNT(*)-COUNT(DISTINCT chave_idempotencia) FROM green_tasks")->fetchColumn();$q=$p->prepare("SELECT status FROM green_service_runs WHERE banco_dados=:db AND servico='ia' ORDER BY codrun DESC LIMIT 1");$q->execute(['db'=>$db]);$ia=(string)($q->fetchColumn()?:'');$out[$db]=['migration_192'=>$migration,'potenciais_aprovados_sem_tarefa'=>$missing,'tarefas_ia'=>$tasks,'alertas_ia'=>$alerts,'auditorias_ia'=>$audits,'chaves_duplicadas'=>$duplicate,'ultima_ia'=>$ia];if($migration!==1||$missing!==0||$duplicate!==0||$ia!=='CONCLUIDA')$ok=false;}
echo json_encode(['ok'=>$ok,'tenants'=>$out],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT).PHP_EOL;exit($ok?0:1);
